function environmentProgressHTML(d,{target=false}={}){
 const p=environmentSupport(d,registry),complete=p.supportedCopies===p.totalCopies;
 return `<section class="environment-support ${target?'target-support':''}" aria-label="${esc(d.name)}の効果対応状況">${target?`<span class="badge green">${complete?'40枚対応済み':'優先して対応中'}</span><h3 class="mt8">${esc(d.name)}</h3>`:''}<div class="row spread mt8"><strong>効果対応 ${p.supportedCopies} / ${p.totalCopies}枚</strong><small>${p.supportedTypes} / ${p.totalTypes}種類</small></div><progress max="${p.totalCopies}" value="${p.supportedCopies}" aria-label="${esc(d.name)}の対応枚数"></progress>${target?`<p class="small">${complete?'40枚の効果に対応し、デッキ全体の自動対戦を検証済みです。手動・自動対戦に使えます。':'現在はカード効果を実装中です。この大会リストでの対戦は、残りの効果対応後に検証します。'}</p><ol class="support-roadmap"><li>1. カード効果</li><li>2. デッキ対戦の検証</li><li class="current">3. AI・分析の改善</li></ol>`:''}<details class="mt8"><summary>カードごとの対応を見る</summary><div class="environment-support-list mt8">${d.cards.map(r=>{const c=card(r.id);return `<div><button class="details-link" data-action="card-detail" data-id="${esc(c.id)}">${esc(c.name)}</button><span class="${c.supported?'green':'muted'}">${r.count}枚 · ${c.supported?'効果対応済み':'未対応'}</span></div>`;}).join('')}</div></details></section>`;
}
function championEntryHTML(role){return `<button class="btn soft full environment-entry" data-action="choose-champions" data-role="${role}" aria-label="${role==='opponent'?'相手':'自分'}の歴代優勝デッキを選ぶ"><span>歴代大会の優勝デッキ</span>${icon('chevron',13)}</button>`;}
async function openChampions(role=championRole){
 if(!['mine','opponent'].includes(role))throw Error('デッキの選択先を確認してください');
 if(!champions){const response=await fetch('champion-decks.json?v='+APP_VERSION,{cache:'no-cache'});if(!response.ok)throw Error('公式優勝デッキを読み込めませんでした');champions=resolveChampions(await response.json(),registry);}
 championRole=role;showDialog(role==='opponent'?'歴代の優勝デッキを相手に選ぶ（オリジナル）':'歴代の優勝デッキを使う（オリジナル）',championsHTML(champions,{role,year:championYear,series:championSeries,availability:championAvailability,art,mark:opponentMark}));
}
function environmentEntryHTML(role,{compact=false}={}){return `<button class="btn soft full environment-entry ${compact?'compact':''}" data-action="choose-environment" data-role="${role}" aria-label="${role==='opponent'?'相手':'自分'}の環境デッキを選ぶ">${icon('spark',16)}<span>環境デッキを選ぶ</span>${icon('chevron',13)}</button>${championEntryHTML(role)}`;}
function environmentHTML({role=editRole,direct=false}={}){
 const fixed=environmentDecks.filter(d=>!d.tournament.practice).length,practiceCount=environmentDecks.length-fixed;
 const opponent=role==='opponent',ordered=[...environmentDecks].sort((a,b)=>Number(deckReadiness(b).kind==='green')-Number(deckReadiness(a).kind==='green'));
 const groups=groupEnvironmentDecks(ordered),yearKey=g=>String(g.year??'unknown'),label=g=>g.year?g.year+'年':'年代未設定',filtered=groups.filter(g=>environmentYearFilter==='all'||yearKey(g)===environmentYearFilter);
 return `<div class="environment-intro"><span class="badge green">環境デッキ ${ordered.length}件</span><h2>${opponent?'大会リストを相手に選ぶ':'大会リストを自分のデッキに'}</h2><p>「対戦可能」のデッキは、40枚すべての効果に対応しています。選ぶと${opponent?'相手用':'自分用'}に保存します。</p><small>${practiceCount?`大会当時の固定リスト${fixed}件と、大会構成を参考にした練習用${practiceCount}件です。`:`大会当時の固定リスト${fixed}件です。当時の構成・使用制限で対戦できます。`}最新ランキングではありません。</small></div><div class="environment-year-filters"><p class="small">大会名の年・年度ごとに表示しています。年を選ぶと絞り込めます。</p><div class="environment-year-buttons" role="group" aria-label="環境デッキを年代で絞り込む"><button class="btn sm ${environmentYearFilter==='all'?'primary':''}" data-action="environment-year" data-year="all" aria-pressed="${environmentYearFilter==='all'}">すべて <span>${ordered.length}</span></button>${groups.map(g=>`<button class="btn sm ${environmentYearFilter===yearKey(g)?'primary':''}" data-action="environment-year" data-year="${yearKey(g)}" aria-pressed="${environmentYearFilter===yearKey(g)}">${label(g)} <span>${g.decks.length}</span></button>`).join('')}</div></div>${filtered.map(g=>`<section class="environment-year-group" data-environment-year="${yearKey(g)}" aria-label="${label(g)}の環境デッキ"><div class="environment-year-heading"><h3>${label(g)}</h3><span class="badge">${g.decks.length}デッキ</span></div><div class="environment-grid ${direct?'environment-picker-grid':''}">${g.decks.map(d=>{
  const ready=deckReadiness(d).kind==='green',action=direct?'pick-environment':'create-environment';
  return `<article class="panel environment-card ${ready?'environment-playable':''}"><div class="row spread wrap">${readinessHTML(d)}${opponent?opponentMark(d):''}<span class="badge">${esc(d.tournament.result)} · ${sum(d)}枚</span></div><div class="environment-preview">${miniDeck(d)}<div class="grow"><h2>${esc(d.name)}</h2><div class="row gap8 mt8">${dots(d)}<small>${d.cards.length}種類</small></div></div></div><div class="environment-card-actions"><button class="btn ${ready?'primary':'soft'} full" data-action="${action}" data-id="${esc(d.id)}" data-role="${role}" aria-label="${esc(d.name)}を${opponent?'相手':'自分'}に${ready?'選ぶ':'登録する（対戦は準備中）'}">${icon(ready?'play':'save',14)}${ready?(opponent?'相手に選ぶ':direct?'自分に選ぶ':'この40枚で作成'):'登録する（対戦は準備中）'}</button></div><p class="source-note mt8">${ready?'40枚対応済み · 手動・自動対戦で使えます。':`効果未対応 ${coverage(d).unsupported}枚 · 登録・編集に利用できます。`}</p><details class="environment-composition mt16"><summary>40枚の構成・対応状況を見る</summary>${environmentProgressHTML(d)}${tournamentHTML(d)}</details></article>`;
 }).join('')}</div></section>`).join('')}<p class="source-note mt16">同じ40枚の保存済みデッキがある場合は、そのデッキを選択します。</p>`;
}
function showEnvironmentPicker(role){environmentYearFilter='all';openEnvironmentPicker(role);}
function refreshEnvironmentYears(){const role=environmentPickerRole;if(dialog.open&&role)openEnvironmentPicker(role);else render();document.querySelector(`[data-action="environment-year"][data-year="${environmentYearFilter}"]`)?.focus({preventScroll:true});}
function openEnvironmentPicker(role){if(!['mine','opponent'].includes(role))throw Error('デッキの保存先を選択してください');showDialog(`${role==='opponent'?'相手':'自分'}の環境デッキを選ぶ`,environmentHTML({role,direct:true}),`<button class="btn" data-action="${role==='opponent'?'choose-opponent':'select-my-deck'}">${icon('back',14)}保存したデッキから選ぶ</button>`);environmentPickerRole=role;}

function createEnvironmentDeck(template){if(!environmentDecks.some(d=>d.id===template?.id))throw Error('大会リストを選択してください');saveCopiedDeck(template,editRole);}
function starter25EntryHTML(role,{compact=false}={}){return `<button class="btn soft full environment-entry ${compact?'compact':''}" data-action="choose-starter25" data-role="${role}" aria-label="${role==='opponent'?'相手':'自分'}の25の王道デッキを選ぶ">${icon('decks',16)}<span>25の王道デッキを選ぶ</span>${icon('chevron',13)}</button>`;}
function starter25SourceHTML(d){const p=d.product;if(p?.code!=='DM26-SD1'||!/^https:\/\/dm\.takaratomy\.co\.jp\/dm26sd1_decklist\/deck\d{2}\/$/.test(p.source))return '';return `<div class="tournament-note"><strong>作成元：${esc(p.title)} / No.${String(p.number).padStart(2,'0')}</strong><p>${esc(p.officialName)}</p><a class="details-link" href="${esc(p.source)}" target="_blank" rel="noopener">公式のデッキ構成・戦い方を確認 ↗</a><small>リスト確認：${esc(p.checkedAt)}。商品の公式リストを参照できます。</small></div>`;}
function starter25HTML({role=editRole,direct=false}={}){
 const opponent=role==='opponent',playable=starterDecks.filter(d=>deckReadiness(d).kind==='green').length,shown=starterDecks.filter(d=>starter25Matches(d,starterQuery,registry)&&(!starterPlayableOnly||deckReadiness(d).kind==='green'));
 return `<div class="environment-intro"><span class="badge green">ドキドキつよいデッキ 25の王道</span><h2>${opponent?'25種類から相手を選ぶ':'25種類から自分のデッキを選ぶ'}</h2><p>公式の40枚を${opponent?'相手用':'自分用'}に登録できます。全25種類で登録・編集が使えます。</p><small>効果付きの対戦に対応済み：${playable} / 25デッキ。未対応カードが残るデッキは、対戦の準備中です。</small></div><div class="starter25-filters"><label for="starter25-search" class="small">番号・デッキ名・カード名で探す</label><input class="field" id="starter25-search" type="search" placeholder="例：No.11、ハチ公、ボルシャック" value="${esc(starterQuery)}"><div class="row gap8 mt8"><button class="btn sm ${starterPlayableOnly?'':'primary'}" data-action="starter25-filter" data-kind="all" aria-pressed="${!starterPlayableOnly}">全25種類</button><button class="btn sm ${starterPlayableOnly?'primary':''}" data-action="starter25-filter" data-kind="playable" aria-pressed="${starterPlayableOnly}">対戦可能 ${playable}</button><small>${shown.length}件</small></div></div><div class="environment-grid ${direct?'environment-picker-grid':''}">${shown.map(d=>{const ready=deckReadiness(d).kind==='green',status=coverage(d);return `<article class="panel environment-card ${ready?'environment-playable':''}"><div class="row spread wrap"><span class="badge">No.${String(d.product.number).padStart(2,'0')}</span>${readinessHTML(d)}${opponent?opponentMark(d):''}</div><div class="environment-preview">${miniDeck(d)}<div class="grow"><h2>${esc(d.name)}</h2><div class="row gap8 mt8">${dots(d)}<small>40枚 · ${d.cards.length}種類</small></div></div></div><p class="small mb16">${esc(d.description)}</p><button class="btn ${ready?'primary':'soft'} full" data-action="${direct?'pick-starter25':'create-starter25'}" data-role="${role}" data-id="${esc(d.id)}">${icon(ready?'play':'save',14)}${ready?(opponent?'相手に選ぶ':'この40枚を使う'):(opponent?'相手用に登録（対戦は準備中）':'この40枚を登録')}</button><p class="source-note mt8">${ready?'手動・自動対戦に使えます。':`効果未対応 ${status.unsupported}枚。登録・編集に使えます。`}</p><details class="environment-composition mt8"><summary>40枚の構成・対応状況を見る</summary>${environmentProgressHTML(d)}${starter25SourceHTML(d)}</details></article>`;}).join('')}</div>${!shown.length?`<div class="empty-state"><h3>${starterPlayableOnly&&!playable?'40枚すべての効果に対応したデッキは、まだありません':'該当するデッキがありません'}</h3><p>「全25種類」に戻すか、検索する言葉を変えてください。</p></div>`:''}<p class="source-note mt16">同じ40枚を保存済みの場合は、そのデッキを選択します。元の公式リストは変更しません。</p>`;
}
function showStarter25Picker(role){if(!['mine','opponent'].includes(role))throw Error('デッキの保存先を選択してください');starterQuery='';starterPlayableOnly=false;showDialog(`${role==='opponent'?'相手':'自分'}の25の王道デッキを選ぶ`,starter25HTML({role,direct:true}),`<button class="btn" data-action="${role==='opponent'?'choose-opponent':'select-my-deck'}">${icon('back',14)}保存したデッキから選ぶ</button>`);starterPickerRole=role;}
function refreshStarter25(){const role=starterPickerRole;if(dialog.open&&role){showDialog(`${role==='opponent'?'相手':'自分'}の25の王道デッキを選ぶ`,starter25HTML({role,direct:true}),`<button class="btn" data-action="${role==='opponent'?'choose-opponent':'select-my-deck'}">保存したデッキから選ぶ</button>`);starterPickerRole=role;}else render();}
function createStarter25Deck(template){if(!starterDecks.some(d=>d.id===template?.id))throw Error('25の王道デッキを選択してください');saveCopiedDeck(template,editRole);}
function saveCopiedDeck(source,target,{nextView=null}={}){const opponent=target==='opponent',collection=opponent?saved.friends:saved.decks,result=prepareDeckCopy(collection,source,registry,{id:uid(),created:new Date().toISOString(),category:opponent?'相手':'自分'});if(!result.alreadyExists)collection.push(result.deck);if(opponent){selectedOpp=result.deck.id;opponentQuery='';allOpp=false;}else saved.selected=result.deck.id;comparisonId=null;edit=null;editRole='mine';clearPhoto();persist();closeDialog();view=nextView||(opponent?'battle':'decks');render();window.scrollTo(0,0);if(storageOK)toast(result.alreadyExists?'同じ40枚のデッキを選択しました':opponent?'相手デッキに登録しました':'40枚の構成でマイデッキを作成しました');}
function openSavedDeck(d){if(!d)return;deckReturnView=view==='deck'?deckReturnView:view;deckViewId=d.id;deckQuery='';closeDialog();view='deck';render();window.scrollTo(0,0);}
function deckContentsHTML(d,{editable=false}={}){
 const total=sum(d),rows=d.cards.filter(r=>r.count&&card(r.id)&&matchesCard(card(r.id),{query:deckQuery})).sort((a,b)=>deckSort==='name'?card(a.id).name.localeCompare(card(b.id).name,'ja'):deckSort==='count'?b.count-a.count||(primaryCost(card(a.id))??Infinity)-(primaryCost(card(b.id))??Infinity):(primaryCost(card(a.id))??Infinity)-(primaryCost(card(b.id))??Infinity)||card(a.id).name.localeCompare(card(b.id).name,'ja'));
 return `<div class="deck-content-toolbar"><div class="search-wrap">${icon('search',17)}<input class="field" id="deck-card-search" placeholder="このデッキのカードを検索" aria-label="デッキ内を検索" value="${esc(deckQuery)}"></div><div class="deck-content-options"><select class="field" id="deck-sort" aria-label="デッキの並び順"><option value="cost" ${deckSort==='cost'?'selected':''}>コスト順</option><option value="name" ${deckSort==='name'?'selected':''}>カード名順</option><option value="count" ${deckSort==='count'?'selected':''}>枚数順</option></select><div class="tabs" role="group" aria-label="カードの表示方法"><button data-action="deck-display" data-display="grid" aria-pressed="${deckDisplay==='grid'}" class="${deckDisplay==='grid'?'active':''}">画像</button><button data-action="deck-display" data-display="list" aria-pressed="${deckDisplay==='list'}" class="${deckDisplay==='list'?'active':''}">リスト</button></div></div></div><div class="deck-content-caption"><span>${deckQuery?'検索結果 '+rows.length+' / ':''}${d.cards.length}種類 · ${total}枚</span><span>画像をタップで能力を確認</span></div><div class="deck-content-cards is-${deckDisplay}">${rows.map(r=>{const c=card(r.id),name=esc(c.name);return `<article class="deck-content-card" data-card-id="${esc(r.id)}"><button class="deck-content-art" data-action="card-detail" data-id="${esc(r.id)}" aria-label="${name}の能力を見る">${art(r.id)}<span class="deck-copy-count">×${r.count}</span></button><div class="deck-content-info"><button class="deck-content-name" data-action="card-detail" data-id="${esc(r.id)}">${name}</button><p>コスト ${esc(costLabel(c))} · ${esc(cardCivilizations(c).join(' / ')||'無色')}</p>${!c.supported?'<small>効果未対応</small>':''}</div>${editable?`<div class="deck-content-edit"><div class="stepper"><button data-action="quantity" data-id="${esc(r.id)}" data-delta="-1" aria-label="${name}を1枚減らす">−</button><span>${r.count}枚</span><button class="add" data-action="quantity" data-id="${esc(r.id)}" data-delta="1" ${r.count>=maxCopies(c)||total>=40?'disabled':''} aria-label="${name}を1枚追加">＋</button></div><button class="icon-btn deck-remove" data-action="remove-editor-card" data-id="${esc(r.id)}" aria-label="${name}をすべて外す" title="このカードをすべて外す">${icon('trash',16)}</button></div>`:`<span class="deck-list-copy">${r.count}枚</span>`}</article>`;}).join('')}</div>${!rows.length?`<div class="empty-state"><p>${deckQuery?'該当するカードがありません。検索条件を変えてください。':'まだカードがありません。カードを追加してデッキを作りましょう。'}</p>${editable&&!deckQuery?'<button class="btn primary mt16" data-action="editor-tab" data-tab="cards">カードを追加する</button>':''}</div>`:''}`;
}
function renderSavedDeck(){const d=saved.decks.find(d=>d.id===deckViewId);if(!d){view='decks';renderDecks();return;}shell(`${pageHead(esc(d.name),'画像と枚数で、デッキ全体を確認できます。',`<div class="toolbar-actions"><button class="btn" data-action="nav" data-view="${deckReturnView==='deck'?'decks':deckReturnView}">${icon('back',14)}戻る</button><button class="btn primary" data-action="edit" data-id="${esc(d.id)}">${icon('edit',14)}編集する</button></div>`,'MY DECK / CARD LIST')}<section class="panel deck-overview"><div><span class="eyebrow">DECK CONTENTS</span><h2>${sum(d)}<small> / 40枚</small><span>${d.cards.length}種類</span></h2></div><div class="deck-overview-meta">${dots(d)}<span class="badge ${registrationErrors(d).length?'amber':coverage(d).unsupported?'':'green'}">${registrationErrors(d).length?'編集中':coverage(d).unsupported?'効果対応待ち':'対戦可能'}</span></div></section><section class="panel deck-content-panel">${deckContentsHTML(d)}</section>`);}
function rememberEdit(){editHistory.push(clone(edit.cards));if(editHistory.length>30)editHistory.shift();}
function refreshEditor(){const y=window.scrollY||0;render();window.scrollTo(0,y);}

function renderEditor(){
 const opponent=editRole==='opponent',editingExisting=(opponent?saved.friends:saved.decks).some(d=>d.id===edit.id),errors=registrationErrors(edit),total=sum(edit);const filtered=cards.filter(c=>matchesCard(c,{query,civ,cost:costFilter,type:typeFilter}));const pages=Math.ceil(filtered.length/18)||1;page=Math.min(page,pages-1);const shown=filtered.slice(page*18,page*18+18);
 const catalogueHTML=`<div class="search-wrap">${icon('search',17)}<input class="field" id="card-search" placeholder="カード名・種族・能力で検索" value="${esc(query)}" aria-label="カード検索"></div><div class="filters mt16"><button class="filter ${!civ?'active':''}" data-action="civ" data-civ="">すべて</button>${Object.keys(color).map(c=>`<button class="filter ${civ===c?'active':''}" data-action="civ" data-civ="${c}"><span class="civ-dot" style="background:${color[c]}"></span>${c}</button>`).join('')}<span class="filter-break" aria-hidden="true"></span><select id="cost-filter" class="filter-select" aria-label="コスト"><option value="">コスト</option><option value="5+" ${costFilter==='5+'?'selected':''}>5以上</option>${cardCosts.map(n=>`<option value="${n}" ${costFilter===String(n)?'selected':''}>${n}</option>`).join('')}<option value="special" ${costFilter==='special'?'selected':''}>数値以外（∞・—など）</option></select><select id="type-filter" class="filter-select" aria-label="種類"><option value="">種類・対応範囲</option><option value="supported" ${typeFilter==='supported'?'selected':''}>対戦対応済み</option><option value="nameOnly" ${typeFilter==='nameOnly'?'selected':''}>効果未対応</option><option value="creature" ${typeFilter==='creature'?'selected':''}>クリーチャー全般</option><option value="spell" ${typeFilter==='spell'?'selected':''}>呪文全般</option>${cardTypes.map(t=>`<option value="${esc(t)}" ${typeFilter===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="result-count">${fmt(filtered.length)}種類 · 同名カードは1種類に集約 · 文明・コスト・種類は同じ面の条件で絞り込み</div><div class="card-grid">${shown.map(c=>{const n=edit.cards.find(r=>r.id===c.id)?.count||0;return `<div class="catalog-card ${n?'included':''}"><button class="card-art-button" data-action="card-detail" data-id="${c.id}" aria-label="${esc(c.name)}の詳細">${art(c.id)}</button><div class="card-name">${esc(c.name)}</div><span class="badge ${c.supported?'green':''}">${c.supported?'対戦対応済み':'効果未対応'}</span><div class="catalog-meta">${esc(cardCivilizations(c).join(' / ')||'文明未掲載')} · コスト ${esc(costLabel(c))}<br>${esc(typeLabel(c))}</div><div class="stepper"><button data-action="quantity" data-id="${c.id}" data-delta="-1" ${n?'':'disabled'} aria-label="${esc(c.name)}を1枚減らす">−</button><span>${n}枚</span><button class="add" data-action="quantity" data-id="${c.id}" data-delta="1" ${n>=maxCopies(c)||total>=40?'disabled':''} aria-label="${esc(c.name)}を1枚追加">＋</button></div></div>`;}).join('')}</div>${!shown.length?'<div class="empty-state"><p>該当するカードがありません。登録済みのカード名や表記を確認してください。</p></div>':''}<div class="pagination"><button class="btn sm" data-action="page" data-delta="-1" ${page===0?'disabled':''}>前へ</button><span>${page+1} / ${pages}</span><button class="btn sm" data-action="page" data-delta="1" ${page+1>=pages?'disabled':''}>次へ</button></div>`;
 shell(`${pageHead(editingExisting?'デッキを編集':opponent?'相手デッキ作成':'デッキ作成',editingExisting?'カードの枚数や組み合わせを調整しよう。':'カードを選んで、40枚の構成をつくろう。',`<div class="toolbar-actions"><button class="btn" data-action="nav" data-view="${editorReturnView}">${icon('back',14)}戻る</button></div>`,opponent?'OPPONENT DECK':'BUILD YOUR DECK')}${editingExisting?'<details class="editor-templates-fold"><summary>環境・王道デッキから作り直す</summary>':''}<div class="editor-environment-entry editor-template-entries mb16"><button class="btn soft full" data-action="editor-tab" data-tab="environment" aria-pressed="${editTab==='environment'}">${icon('spark',16)}環境デッキを選ぶ</button><button class="btn soft full" data-action="editor-tab" data-tab="starter25" aria-pressed="${editTab==='starter25'}">${icon('decks',16)}25の王道デッキを選ぶ</button></div>${editingExisting?'</details>':''}<div class="editor-toolbar"><input class="field" id="deck-name" aria-label="デッキ名" value="${esc(edit.name)}" maxlength="50"><span class="badge">${icon('lock',11)}この端末のみ</span><span class="badge mobile-hide">オリジナル</span></div><div class="editor-layout"><section class="panel"><div class="tabs dark-active mb16 editor-method-tabs"><button data-action="editor-tab" data-tab="deck" class="${editTab==='deck'?'active':''}">デッキ内容</button><button data-action="editor-tab" data-tab="cards" class="${editTab==='cards'?'active':''}">カードを追加</button><button data-action="editor-tab" data-tab="support" class="${editTab==='support'?'active':''}">スクショから40枚</button><button data-action="editor-tab" data-tab="photo" class="${editTab==='photo'?'active':''}">${icon('camera',14)} 写真から登録</button></div>${editTab==='deck'?`<div class="deck-edit-heading"><div><h2>いまのデッキ</h2><p class="small">＋・−で枚数変更。外したカードは元に戻せます。</p></div><button class="btn soft" data-action="editor-tab" data-tab="cards">${icon('plus',15)}カードを追加</button></div><button class="btn sm deck-edit-undo" data-action="undo-deck-edit" ${editHistory.length?'':'disabled'}>${icon('history',14)}元に戻す</button>${deckContentsHTML(edit,{editable:true})}`:editTab==='cards'?catalogueHTML:editTab==='environment'?environmentHTML():editTab==='starter25'?starter25HTML():editTab==='support'?supportScreenshotHTML(photo,registry,{busy:ocrBusy,icon,role:editRole}):photoHTML()}</section><aside class="panel editor-summary"><div class="desktop-summary-label eyebrow mb16">${opponent?'OPPONENT DECK':'YOUR DECK'}</div><div class="summary-count-row"><div class="row spread"><div><div class="small">デッキの枚数</div><div class="count-big ${total===40?'green':''}">${total}<small>/ 40 枚</small></div></div><span class="badge green desktop-summary-label">${total===40?'登録OK':`あと${40-total}枚`}</span></div><button class="btn primary full mt16 summary-save" data-action="save-deck" ${errors.length?'disabled':''}>${icon('save',15)}${opponent?'相手デッキを保存':'デッキを保存'}</button></div><div class="curve-section mt24"><h3>コストバランス</h3><small>面1の数値コストを集計</small>${curve(edit)}</div><div class="deck-list">${edit.cards.filter(r=>r.count).sort((a,b)=>(primaryCost(card(a.id))??Infinity)-(primaryCost(card(b.id))??Infinity)).map(r=>`<div class="deck-list-row"><span class="cost-small cost-summary" title="コスト ${esc(costLabel(card(r.id)))}">${esc(costLabel(card(r.id)))}</span><span class="grow">${esc(card(r.id).name)}</span><strong>${r.count}</strong><button class="icon-btn" data-action="quantity" data-id="${r.id}" data-delta="-1" aria-label="1枚減らす">−</button></div>`).join('')}</div><div class="summary-end mt16"><small>${errors.length?esc(errors[0]):'登録枚数を確認済みです。効果未対応カードの使用制限・特殊な構築条件は未確認です。'}</small></div></aside></div>`);
}
function photoHTML(){return `<input type="file" class="file-input" id="photo-file" accept="image/*"><input type="file" class="file-input" id="camera-file" accept="image/*" capture="environment"><div class="tabs mb16"><button class="${photo?.source==='screenshot'?'':'active'}" data-action="photo-source" data-source="photo">カード写真</button><button class="${photo?.source==='screenshot'?'active':''}" data-action="photo-source" data-source="screenshot">スクリーンショット</button></div>${photo?.url?`<img class="image-preview" src="${photo.url}" alt="読み取り対象の画像"><div class="row spread mt8"><small>画像は端末内で処理します</small><button class="details-link" data-action="choose-photo">画像を変更</button></div>`:`<div class="upload-zone"><div class="round-icon">${icon('camera',28)}</div><h3>写真からデッキを読み込む</h3><p>カード名を読み取り、候補を確認して登録します。</p><div class="upload-actions"><button class="btn primary" data-action="take-photo">${icon('camera',16)}撮影する</button><button class="btn" data-action="choose-photo">${icon('upload',16)}画像を選択</button></div></div>`}${ocrBusy?`<div class="mt16"><div class="row spread"><h3>日本語を読み取り中…</h3><span id="ocr-percent" class="small">準備中</span></div><div class="ocr-progress"><span id="ocr-bar" style="width:5%"></span></div><p class="photo-tip">初回は日本語辞書の準備に少し時間がかかります。</p></div>`:''}${photo?.rows?.length?`<div class="row spread mt24"><h3>読み取り結果</h3><span class="badge amber">${photo.rows.filter(r=>!r.confirmed).length}件を確認</span></div><p class="photo-tip">枚数は候補です。カードと枚数を確認し、チェックしてください。</p>${photo.rows.map((r,i)=>`<div class="review-row ${r.confirmed?'':'uncertain'}">${r.id?art(r.id):`<span class="badge amber">?</span>`}<div class="grow"><button class="btn ocr-pick-button" data-action="ocr-pick" data-index="${i}">${esc(card(r.id)?.name||'カード名を選択')} ${icon('search',14)}</button><small>${esc(r.original||'カード名を確認')}</small></div><div class="stepper"><button data-action="ocr-count" data-index="${i}" data-delta="-1" ${r.count<=1?'disabled':''}>−</button><span>${r.count}枚</span><button class="add" data-action="ocr-count" data-index="${i}" data-delta="1" ${r.count>=(r.id?maxCopies(card(r.id)):40)?'disabled':''}>＋</button></div><input type="checkbox" class="ocr-confirm" data-index="${i}" ${r.confirmed?'checked':''} ${r.id?'':'disabled'} aria-label="カードと枚数を確認済みにする"></div>`).join('')}<button class="btn primary full mt16" data-action="ocr-add" ${ocrBusy||photo.rows.some(r=>!r.confirmed||!r.id)?'disabled':''}>確認してデッキへ追加</button>`:''}${photo?.url&&!ocrBusy&&!photo.rows?.length?`<div class="mt16">${notice(photo.error||'画像を選択しました。読み取りを開始できます。',photo.error?'amber':'')}<button class="btn primary full mt16" data-action="read-photo">${icon('spark',15)}カード名を読み取る</button></div>`:''}<div class="mt16">${notice(`${fmt(cards.length)}種類のカード名を候補にします。実物は重ねず、名前が読める大きさで撮影してください。枚数・不鮮明な文字は必ず確認してください。`)}</div>${photo?.text?`<details class="mt16"><summary class="small">読み取った文字を確認・修正</summary><textarea class="field text-area mt8" id="ocr-text">${esc(photo.text)}</textarea><button class="btn sm mt8" data-action="reparse-photo">この文字から候補を作る</button></details>`:''}`;}
const chancePct=n=>n>0&&n<.001?new Intl.NumberFormat('ja-JP',{maximumSignificantDigits:2,useGrouping:false}).format(n*100):pct(n);
const randomSeed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
function deckReadiness(d){
 const invalid=registrationErrors(d);if(invalid.length)return {label:'構成を確認',kind:'amber'};
 const unsupported=coverage(d).unsupported;if(unsupported)return {label:'登録のみ・効果対応待ち',kind:'amber'};
 return validateDeck(d).length?{label:'構成・使用制限を確認',kind:'amber'}:{label:'対戦可能',kind:'green'};
}
function readinessHTML(d){const r=deckReadiness(d);return `<span class="badge readiness ${r.kind}">${r.kind==='green'?icon('check',11):icon('info',11)}${r.label}</span>`;}
function randomOpponentHTML(){return `<div class="random-opponent"><button type="button" class="btn full" data-action="random-opponent" aria-label="相手デッキをランダムで選ぶ">${icon('shuffle',16)}ランダムで選ぶ</button><small>保存済み・環境・25の王道から</small></div>`;}
function matchDeckHTML(d,label,action,buttonLabel){return `<article class="match-deck ${label==='相手'?'opponent-selected':''}"><div class="row spread"><small>${label}</small><button class="details-link" data-action="${action}" aria-label="${buttonLabel}">${d?'変更':'選ぶ'} ${icon('chevron',12)}</button></div><div class="match-deck-info">${d?`${miniDeck(d)}<div class="grow"><h3>${esc(d.name)}</h3><small>${sum(d)}枚 · オリジナル</small></div>`:`<span class="match-deck-placeholder">${icon('decks',28)}</span><div class="grow"><h3>相手を選ぼう</h3><small>保存済み・環境デッキから</small></div>`}</div>${d?readinessHTML(d):'<span class="badge">未選択</span>'}${label==='相手'?randomOpponentHTML()+(d&&d.id===randomOpponent?.id?`<button class="details-link" data-action="deck-detail" data-id="${esc(d.id)}">リスト ${icon('chevron',11)}</button>`:''):''}${environmentEntryHTML(label==='相手'?'opponent':'mine',{compact:true})}${starter25EntryHTML(label==='相手'?'opponent':'mine',{compact:true})}</article>`;}
function randomOpponentCandidates(){
 const unique=new Map();
 for(const d of [...opponentDecks(),...saved.decks,...environmentDecks,...starterDecks]){
  if(registrationErrors(d).length||coverage(d).unsupported||validateDeck(d).length)continue;
  const signature=JSON.stringify(registry.resolveRows(d.cards).sort((a,b)=>a.id.localeCompare(b.id)));
  if(!unique.has(signature))unique.set(signature,{deck:d,signature});
 }
 return [...unique.values()];
}
function chooseRandomOpponent(){
 const candidates=randomOpponentCandidates();if(!candidates.length){toast('対戦可能なデッキがありません。40枚の構成と対応状況を確認してください');return;}
 const current=selectedOpponent(),signature=current?JSON.stringify(registry.resolveRows(current.cards).sort((a,b)=>a.id.localeCompare(b.id))):null,others=candidates.filter(x=>x.signature!==signature),pool=others.length?others:candidates;
 const chosen=pool[Math.floor(crypto.getRandomValues(new Uint32Array(1))[0]/4294967296*pool.length)].deck;
 randomOpponent={...clone(chosen),id:uid(),category:'相手'};selectedOpp=randomOpponent.id;opponentQuery='';allOpp=false;comparisonId=null;
 closeDialog();view='battle';render();toast('相手：'+randomOpponent.name);
}
function matchBlockReason(d,targets){
 if(!targets.length||targets.some(x=>!x))return '相手デッキを選ぶと、対戦を開始できます。';
 if(registrationErrors(d).length||targets.some(x=>registrationErrors(x).length))return 'デッキの枚数や構成を確認してください。';
 const mine=coverage(d).unsupported,opponents=targets.reduce((n,x)=>n+coverage(x).unsupported,0);
 if(mine||opponents)return `${[mine?`自分の${mine}枚`:null,opponents?`相手の${opponents}枚`:null].filter(Boolean).join('・')}のカード効果が未対応です。`;
 return [...validateDeck(d),...targets.flatMap(x=>validateDeck(x))].length?'デッキの構成・使用制限を確認してください。':'';
}
function renderMatch(){if(!myDeck()){shell(`${onlineEntryHTML()}${pageHead('対戦する','まずは自分のデッキを登録しましょう。')}<div class="empty-state">${icon('decks',45)}<h2>デッキがまだありません</h2><p>カード一覧または写真から登録できます。</p><button class="btn primary" data-action="new-deck">デッキを作成</button><div class="mt16">${environmentEntryHTML('mine')}${starter25EntryHTML('mine')}</div></div>`);return;}
 const opponents=opponentDecks(),filtered=opponents.filter(d=>!opponentQuery||d.name.includes(opponentQuery));
 const d=myDeck(),o=selectedOpponent(),base=comparisonId?saved.history.find(r=>r.id===comparisonId):null,targets=mode==='auto'?simulationOpponents(base):[o],reason=matchBlockReason(d,targets),multiple=mode==='auto'&&(allOpp||!!base),targetName=multiple?`${targets.length}デッキ`:o?.name||'未選択',actualCount=base?.count||count,actualFirst=mode==='auto'&&base?base.first:first;
 const summary=multiple?`<article class="match-deck opponent-selected"><div class="row spread"><small>相手</small><button class="details-link" data-action="choose-opponent">1つ選ぶ ${icon('chevron',12)}</button></div><div class="match-deck-info"><span class="match-deck-placeholder">${icon('decks',28)}</span><div class="grow"><h3>${base?'履歴と同じ相手':'登録した相手すべて'}</h3><small>${targets.length}デッキ · 合計${fmt(actualCount*targets.length)}戦</small></div></div><span class="badge ${reason?'amber':'green'}">${reason?'対戦できないデッキあり':'対戦可能'}</span>${randomOpponentHTML()}${environmentEntryHTML('opponent',{compact:true})}${starter25EntryHTML('opponent',{compact:true})}</article>`:matchDeckHTML(o,'相手','choose-opponent','相手デッキを変更');
 shell(`${onlineEntryHTML()}<button class="hero-entry" data-action="nav" data-view="challenge"><span><strong>主人公・ライバルチャレンジ</strong><small>主人公4人とライバル4人の切り札に挑む</small></span><span aria-hidden="true">→</span></button>${pageHead('対戦の準備','デッキと相手を確認して、対戦しよう。','','READY TO DUEL')}<section class="match-overview" aria-label="対戦するデッキ">${matchDeckHTML(d,'自分','select-my-deck','自分のデッキを変更')}${summary}</section>${base?`<div class="mb16">${notice(`対戦履歴と同じ相手・回数・先後・乱数条件で比較します。<br>${esc(base.results.map(r=>r.opponent.name).join(' / '))}`)}</div>`:''}<div class="match-layout"><section><div class="panel"><div class="panel-title"><h2>相手を用意する</h2><span class="badge">保存 ${opponents.length}デッキ</span></div>${opponentSourcesHTML()}<h3 class="mt24 mb16">登録した相手から選ぶ</h3><div class="search-wrap">${icon('search',17)}<input class="field" id="opponent-search" placeholder="デッキ名で検索" value="${esc(opponentQuery)}"></div><div class="mt16"></div>${filtered.map(o=>`<div class="opponent ${!multiple&&selectedOpp===o.id?'active':''}" role="button" tabindex="0" data-action="select-opponent" data-id="${esc(o.id)}" aria-pressed="${!multiple&&selectedOpp===o.id}">${miniDeck(o)}<div class="grow"><h3>${esc(o.name)}</h3>${opponentMark(o)}<div class="row gap8"><span class="badge ${o.tournament?'green':'purple'}">${esc(o.tournament?'環境':o.category)}</span>${dots(o)}<small>${sum(o)}枚</small></div><div class="mt8">${readinessHTML(o)}</div><button class="details-link" data-action="deck-detail" data-id="${esc(o.id)}">構成を見る ${icon('chevron',11)}</button><button class="details-link opponent-edit" data-action="edit-opponent" data-id="${esc(o.id)}">${icon('edit',11)} 編集</button></div><span class="radio">${!multiple&&selectedOpp===o.id?icon('check',13):''}</span></div>`).join('')}${!filtered.length?`<div class="empty-state">${icon('decks',33)}<h3>${opponents.length?'検索に一致する相手がありません':'相手デッキがまだありません'}</h3><p class="mt8">${opponents.length?'デッキ名を変えて検索してください。':'新しく作るか、保存済み・環境デッキから選べます。'}</p><button class="btn" data-action="new-opponent">相手デッキを作る</button></div>`:''}</div></section><aside class="panel setup-card"><div class="eyebrow mb16">MATCH SETTINGS</div><h2 class="mb16">対戦設定</h2>${reason?`<div class="mb16">${notice(esc(reason)+'','amber')}</div>`:''}<div class="tabs dark-active"><button class="${mode==='auto'?'active':''}" data-action="mode" data-mode="auto">${icon('bolt',14)} 自動対戦</button><button class="${mode==='manual'?'active':''}" data-action="mode" data-mode="manual">${icon('battle',14)} 手動対戦</button></div>${mode==='auto'?`<div class="setup-line"><label for="match-count">対戦回数${multiple?'（相手ごと）':''}</label><select class="field" id="match-count" ${base?'disabled':''}>${[100,500,1000,3000].map(n=>`<option value="${n}" ${actualCount===n?'selected':''}>${fmt(n)} 回</option>`).join('')}</select></div>`:''}<div class="setup-line"><label for="match-first">先攻・後攻</label><select class="field" id="match-first" ${base&&mode==='auto'?'disabled':''}><option value="random" ${actualFirst==='random'?'selected':''}>${mode==='auto'?'交互に入れ替え':'ランダム'}</option><option value="first" ${actualFirst==='first'?'selected':''}>先攻</option><option value="second" ${actualFirst==='second'?'selected':''}>後攻</option></select></div><div class="setup-line"><span>ルール</span><span class="badge">オリジナル</span></div>${mode==='auto'?`<label class="checkbox-row mt8"><input type="checkbox" id="all-opponents" ${allOpp?'checked':''} ${!opponents.length||base?'disabled':''}>登録した相手すべてと対戦</label>`:`<label class="checkbox-row mt8"><input type="checkbox" id="practice-mode" ${practice?'checked':''}>練習モード（ヒント・待った）</label>`}<p class="source-note mt16">${mode==='auto'?'各試合をカードの処理から実行して集計します。相手AIは非公開の手札・山札・シールドを参照しません。':'カードや行動を自分で選択し、相手はAIが操作します。'}</p><button class="details-link mt8" data-action="about">対応カード・ルールを確認 ${icon('chevron',11)}</button><div class="match-start" aria-label="対戦の開始"><div class="match-start-inner"><div class="match-start-summary"><span>${mode==='auto'?targets.filter(Boolean).length?`自動対戦 · 合計${fmt(actualCount*targets.filter(Boolean).length)}戦`:'自動対戦 · 相手未選択':'手動対戦 · 1戦'}</span><button class="details-link" data-action="match-settings">設定 ${icon('settings',13)}</button></div><div class="match-start-names"><span>${esc(d.name)}</span><b>VS</b><span>${esc(targetName)}</span></div><p id="match-block-reason" class="match-start-reason ${reason?'blocked':''}">${esc(reason||'デッキの準備ができました。')}</p><button class="btn primary full" data-action="start-match" aria-describedby="match-block-reason" ${running||reason?'disabled':''}>${icon('play',16)}${mode==='auto'?'シミュレーション開始':'対戦をはじめる'}</button><div class="match-mode-switch" role="group" aria-label="対戦方法"><button type="button" data-action="mode" data-mode="manual" aria-pressed="${mode==='manual'}">${icon('battle',15)}手動</button><button type="button" data-action="mode" data-mode="auto" aria-pressed="${mode==='auto'}">${icon('bolt',15)}自動</button></div></div></div></aside></div>`);
}
function combinedStats(results){const keys=['total','wins','losses','unresolved','completed','earlyCreatures'];const out=Object.fromEntries(keys.map(k=>[k,results.reduce((s,r)=>s+(r.stats[k]||0),0)]));out.rate=out.completed?out.wins/out.completed:0;out.averageTurns=out.completed?results.reduce((s,r)=>s+r.stats.averageTurns*r.stats.completed,0)/out.completed:0;out.groups=[0,1].map(i=>({count:results.reduce((s,r)=>s+r.stats.groups[i].count,0),wins:results.reduce((s,r)=>s+r.stats.groups[i].wins,0)}));out.cards={};for(const r of results)for(const[id,x]of Object.entries(r.stats.cards)){out.cards[id]||={count:0,wins:0};out.cards[id].count+=x.count;out.cards[id].wins+=x.wins;}const z=1.96,n=out.completed,p=out.rate,den=1+z*z/(n||1),center=(p+z*z/(2*(n||1)))/den,half=z*Math.sqrt(p*(1-p)/(n||1)+z*z/(4*(n||1)**2))/den;out.interval=n?[Math.max(0,center-half),Math.min(1,center+half)]:null;return out;}
function startSimulation(deck,options={}){
 if(running)return;const errors=validateDeck(deck);if(errors.length){toast(errors[0]);return;}
 const base=comparisonId?saved.history.find(r=>r.id===comparisonId):null;
 const opponents=options.opponents||simulationOpponents(base);if(!opponents.length||opponents.some(d=>!d)){toast('相手デッキを選択してください');return;}
 const opponentErrors=opponents.flatMap(d=>validateDeck(d));if(opponentErrors.length){toast('相手デッキ：'+opponentErrors[0]);return;}
 const n=options.count||base?.count||count,seed=options.seed??base?.seed??crypto.getRandomValues(new Uint32Array(1))[0],f=options.first||base?.first||first;
 running={completed:0,total:n*opponents.length,current:opponents[0].name,deck:clone(deck),count:n,seed,first:f,opponents:clone(opponents),baseline:base?.id||null};view='analysis';render();
 worker=new Worker(new URL('./worker.js?v=0.137.0',import.meta.url),{type:'module'});
 worker.onmessage=({data})=>{
  if(data.type==='progress'){if(!running)return;Object.assign(running,data);renderProgress();}
  if(data.type==='done'){
   const r=running;if(!r)return;worker.terminate();worker=null;const results=data.results.map(x=>({...x,games:undefined,samples:[...x.games.filter(g=>g.winner===0).slice(0,4),...x.games.filter(g=>g.winner===1).slice(0,4),...x.games.filter(g=>g.winner===null).slice(0,2)]}));
   activeRun={id:uid(),created:new Date().toISOString(),deck:r.deck,count:r.count,seed:r.seed,first:r.first,results,stats:combinedStats(results),baseline:r.baseline,version:ENGINE_VERSION,aiVersion:AI_VERSION,rules:RULE_VERSION,checkedAt:metadata.checkedAt};saved.history.unshift(activeRun);saved.history=saved.history.slice(0,16);persist();running=null;comparisonId=null;view='analysis';render();toast('対戦が完了しました');
  }
  if(data.type==='error'){running=null;worker?.terminate();worker=null;toast('対戦を実行できませんでした：'+data.message);render();}
 };
 worker.onerror=()=>{running=null;worker?.terminate();worker=null;toast('対戦処理を読み込めませんでした。再読み込みして試してください');render();};
 worker.postMessage({cards:battleCards,deck:clone(deck),opponents,count:n,seed,first:f});
}
function renderProgress(){if(view!=='analysis')return;const r=running;if(!r)return;const percent=Math.round(r.completed/r.total*100);shell(`${pageHead('シミュレーション中','対戦を1戦ずつ実行しています。','','SIMULATING')}<div class="panel loading-panel"><div class="row spread"><span class="badge green"><span class="running-dot"></span>実行中</span><span class="small">オリジナル · ${battleCards.length}種類の効果に対応</span></div><div class="progress-ring"></div><h2>${esc(r.deck.name)} vs ${esc(r.current)}</h2><p class="muted mt8">${fmt(r.completed)} / ${fmt(r.total)} 戦</p><div class="progress-track"><span style="width:${percent}%"></span></div><div class="row spread mt8"><small>対戦処理・集計</small><small>${percent}%</small></div>${r.stats?`<div class="stats-grid mt24"><div class="metric"><small>現在の勝率</small><strong class="green">${pct(r.stats.rate)}%</strong></div><div class="metric"><small>勝利</small><strong>${fmt(r.stats.wins)}</strong></div><div class="metric"><small>敗北</small><strong>${fmt(r.stats.losses)}</strong></div></div>`:''}<button class="btn run-cancel" data-action="cancel-run">実行を中止</button></div>`);}
function resultBar(s){return `<div class="winbar"><span class="win" style="width:${s.total?s.wins/s.total*100:0}%"></span><span class="unresolved" style="width:${s.total?s.unresolved/s.total*100:0}%"></span></div><div class="row spread mt8"><strong class="green small">${fmt(s.wins)}勝</strong><span class="small">${s.unresolved?`未決着 ${s.unresolved}戦`:''}</span><strong class="red small">${fmt(s.losses)}敗</strong></div>`;}
function insights(r){const s=r.stats,eligible=Object.entries(s.cards).filter(([,v])=>v.count>=10).sort((a,b)=>b[1].wins/b[1].count-a[1].wins/a[1].count),top=eligible[0],earlyRate=s.total?s.earlyCreatures/s.total:0;return `<div class="insight"><span class="insight-icon">${icon('bolt',17)}</span><div><h3>序盤の展開をチェック</h3><p>自分の3ターン目までにクリーチャーを召喚した対戦は ${fmt(s.earlyCreatures)} / ${fmt(s.total)}戦（${pct(earlyRate)}%）です。</p><small>${earlyRate<.8?'低コストの枚数や文明の配分を見直し、改良前後で比較できます。':'次は相手のブロッカーや除去への対応を対戦記録で確認しましょう。'}</small></div></div>${top?`<div class="insight"><span class="insight-icon">${icon('spark',17)}</span><div><h3>序盤に使ったカードと勝率</h3><p>「${esc(card(top[0]).name)}」を3ターン目までに使った${top[1].count}戦では、勝率 ${pct(top[1].wins/top[1].count)}%でした。</p><small>使用と勝利の関係を示す集計です。勝因と断定するものではありません。</small></div></div>`:''}<div class="insight"><span class="insight-icon">${icon('shield',17)}</span><div><h3>苦手な相手を掘り下げる</h3><p>${esc([...r.results].sort((a,b)=>a.stats.rate-b.stats.rate)[0]?.opponent.name)}との相性を、シールドが減った場面・除去された場面から見返せます。</p><button class="details-link mt8" data-action="sample-replay" data-run="${r.id}" data-outcome="loss">負けた対戦を見返す ${icon('chevron',12)}</button></div></div>`;}
function renderAnalysis(){if(running){renderProgress();return;}const r=activeRun||saved.history[0];if(!r){shell(`${pageHead('分析・比較','自動対戦の結果から、次の1枚を考えよう。','','PERFORMANCE')}<div class="panel empty-state">${icon('analysis',44)}<h2>最初の分析をはじめよう</h2><p>デッキと相手を選んで自動対戦すると、ここに結果が表示されます。</p><button class="btn primary" data-action="nav" data-view="battle">${icon('play',15)}対戦を準備する</button></div>`);return;}activeRun=r;const s=r.stats,before=r.baseline?saved.history.find(h=>h.id===r.baseline):null;
 shell(`${pageHead('対戦の結果','実行した対戦の記録から、デッキの強みと課題を確認。',`<button class="btn" data-action="run-export" data-id="${r.id}">${icon('download',15)}結果を書き出す</button>`,'SIMULATION REPORT')}<div class="run-layout"><section class="stack"><div class="panel"><div class="matchup"><div class="matchup-side"><strong>${esc(r.deck.name)}</strong>${miniDeck(r.deck)}</div><span class="versus">VS</span><div class="matchup-side"><strong>${esc(r.results.length>1?`${r.results.length}種類の相手`:r.results[0].opponent.name)}</strong>${miniDeck(r.results[0].opponent)}</div></div><div class="run-top mt16"><span class="row gap8"><span class="check-circle">${icon('check',13)}</span><strong>シミュレーション完了</strong></span><span class="muted">${fmt(s.total)}戦</span></div><div class="small">${r.results.length>1?'選択した相手全体の':'この相手との'}勝率</div><div class="win-number">${pct(s.rate)}<span>%</span></div>${resultBar(s)}<p class="confidence">95%信頼区間 ${s.interval?`${pct(s.interval[0])}–${pct(s.interval[1])}%`:'算出不可'} · 未決着は勝率から除外</p><div class="stats-grid"><div class="metric"><small>先攻の勝率</small><strong>${s.groups[0].count?pct(s.groups[0].wins/s.groups[0].count)+'%':'—'}</strong><small>${fmt(s.groups[0].count)}戦</small></div><div class="metric"><small>後攻の勝率</small><strong>${s.groups[1].count?pct(s.groups[1].wins/s.groups[1].count)+'%':'—'}</strong><small>${fmt(s.groups[1].count)}戦</small></div><div class="metric"><small>平均決着ターン</small><strong>${s.averageTurns.toFixed(1)}</strong><small>両者の合計ターン</small></div></div></div>${before?`<div class="panel"><div class="panel-title"><h2>改良前後の比較</h2><span class="badge green">同じ対戦条件</span></div><div class="compare-grid"><div><small>改良前 · ${esc(before.deck.name)}</small><div class="compare-rate">${pct(before.stats.rate)}%</div></div><div><small>改良後 · ${esc(r.deck.name)}</small><div class="compare-rate">${pct(s.rate)}%</div></div></div><p class="small mt16">差は ${(s.rate-before.stats.rate)*100>=0?'+':''}${((s.rate-before.stats.rate)*100).toFixed(1)} ポイント。乱数・相手・回数・先後をそろえた結果です。サンプルのばらつきも含まれます。</p><button class="details-link mt8" data-action="compare-detail" data-id="${r.id}">カードの変更内容を見る ${icon('chevron',12)}</button></div>`:''}<div class="panel"><div class="panel-title"><h2>相手別の勝率</h2><span class="small">実行結果</span></div>${r.results.map((x,i)=>`<div class="matchup-row"><span class="label">${esc(x.opponent.name)}</span><div class="bar-track"><span style="width:${x.stats.rate*100}%"></span></div><strong class="green small">${pct(x.stats.rate)}%</strong><button class="icon-btn" data-action="result-detail" data-run="${r.id}" data-index="${i}" aria-label="この相手との記録">${icon('chevron',15)}</button></div>`).join('')}</div><div class="panel"><div class="panel-title"><h2>序盤に使ったカード</h2><span class="badge">3ターン目まで</span></div><div class="table-wrap"><table><thead><tr><th>カード</th><th>使用した対戦</th><th>そのときの勝率</th></tr></thead><tbody>${Object.entries(s.cards).sort((a,b)=>b[1].count-a[1].count).map(([id,x])=>`<tr><td><button class="details-link" data-action="card-detail" data-id="${id}">${esc(card(id)?.name||id)}</button></td><td>${fmt(x.count)}戦</td><td>${pct(x.wins/x.count)}%</td></tr>`).join('')}</tbody></table></div><p class="source-note mt16">各カードを使った対戦は重複します。カード単体の効果を分離した数値ではありません。</p></div></section><aside class="stack"><div class="panel"><div class="panel-title"><h2>勝敗のポイント</h2>${icon('analysis',17)}</div>${insights(r)}<button class="btn primary full mt16" data-action="improve" data-id="${r.id}" ${r.version!==ENGINE_VERSION?'disabled':''}>${icon('edit',15)}デッキを改良して比較</button>${r.version!==ENGINE_VERSION?'<p class="source-note mt8">旧バージョンの結果です。現在のエンジンで対戦し直すと、同じ条件での比較が使えます。</p>':''}</div><div class="panel"><h3>対戦を見返す</h3><p class="small mt8">実際の行動とカードの処理を、順番に確認できます。</p><div class="row mt16"><button class="btn grow" data-action="sample-replay" data-run="${r.id}" data-outcome="win">勝った対戦</button><button class="btn grow" data-action="sample-replay" data-run="${r.id}" data-outcome="loss">負けた対戦</button></div></div><div class="panel"><h3>分析の条件</h3><ul class="source-list"><li>実行：${date(r.created)}</li><li>カード・制限確認：${r.checkedAt}</li><li>${esc(r.rules)}</li><li>AI：${r.aiVersion?`先読み v${esc(r.aiVersion)}`:`ルールベース v${esc(r.version)}`}</li><li>各相手 ${fmt(r.count)}戦 / ${r.first==='random'?'先後交互':r.first==='first'?'先攻固定':'後攻固定'}</li></ul><p class="source-note">このアプリ内の対戦結果です。実際の大会勝率とは区別してください。</p></div></aside></div>`);
}
function renderHistory(){shell(`${pageHead('対戦履歴','過去の結果も、改良のヒントに。','','YOUR PROGRESS')}${saved.history.length?saved.history.map(r=>`<article class="history-item" data-action="open-run" data-id="${r.id}" role="button" tabindex="0"><div class="history-rate">${pct(r.stats.rate)}<small>%</small></div><div class="grow"><h3>${esc(r.deck.name)}</h3><p>${esc(r.results.map(x=>x.opponent.name).join(' / '))}</p><div class="row gap8 mt8"><span class="badge">${fmt(r.stats.total)}戦</span><small>${date(r.created)}</small>${r.baseline?'<span class="badge green">改良版</span>':''}</div></div>${icon('chevron',18)}</article>`).join(''):`<div class="panel empty-state">${icon('history',42)}<h2>対戦の記録はまだありません</h2><p>自動対戦を実行すると、結果をこの端末に保存します。</p><button class="btn primary" data-action="nav" data-view="battle">対戦をはじめる</button></div>`}<p class="source-note mt16">最新16件をこのブラウザに保存します。各結果には代表的な対戦の再現用データを保存しています。</p>`);}
