 if(changed){const viewingHand=manualUI.mobilePanel==='card'&&model.hand;manualUI.filter='';manualUI.choicePage=0;manualUI.confirm=null;manualUI.attackChoice=null;manualUI.handOpen=false;if(model.human||s.winner!==null)manualUI.panelMinimized=false;manualUI.mobilePanel=(model.human&&s.decision)||s.winner!==null?'actions':viewingHand?manualUI.mobilePanel:'closed';}
 if(!previewAttackAction(s,manualUI))manualUI.attackChoice=null;
 manualUI.hand=model.hand?.uid||null;selectedHand=manualUI.hand;manualUI.attacker=model.attacker;manualUI.context=model.context;
 shell(manualScreenHTML(s,manualUI,{art,icon,displayCard:card,practice:battle.practice,undoCount:battleUndo.length}));
 const manaTrack=$('.mana-card-track');if(manaTrack)manaTrack.scrollLeft=manaScroll;
 const shelf=$('.hand-shelf-cards');if(shelf)shelf.scrollLeft=shelfScroll;
 const hand=$('.manual-hand-cards');if(hand)hand.scrollLeft=handScroll;
 const board=$('.manual-board-area');if(board)board.scrollTop=boardScroll;
 document.querySelectorAll('.play-creatures,.shield-tiles').forEach((el,i)=>el.scrollLeft=lanes[i]||0);
 const controls=$('.manual-console-content');if(controls){controls.dataset.selectedHand=manualUI.hand||'';controls.scrollTop=handChanged?0:controlsScroll;}
 const choices=$('.manual-choices');if(choices)choices.scrollTop=choiceScroll;
 applyAIHighlights(board,manualUI.aiPlayback?.cue);
 const stopFit=manualUI.mobile?bindFittedBoard(board,window):()=>{},stopArrow=bindAttackArrow(board,$('.attack-overlay'),attackRoute(s,manualUI),window);manualVisualCleanup=()=>{stopFit();stopArrow();};
 if(handChanged&&manualUI.mobilePanel==='card')$('.hand-inspector h3')?.focus({preventScroll:true});
 else if(focusKey&&(!changed||focusKey.startsWith('mana-')))document.querySelector(`[data-focus-key="${CSS.escape(focusKey)}"]`)?.focus({preventScroll:true});
