function humanAction(i,confirmed=false,number=undefined){
 if(!battle)return;const s=battle.state,a=getLegalActions(s)[Number(i)];if(!a||a.player!==0)return;if(number!==undefined){if(s.decision?.task?.op!=='g9Number'||!(number==='∞'||Number.isSafeInteger(number)&&number>=0))return;a.number=number;}manualUI.panelMinimized=false;manualUI.mobilePanel='actions';
 if(!confirmed&&a.kind==='attack'){manualUI.attackChoice=clone(a);manualUI.attacker=a.uid;manualUI.confirm=null;manualUI.mobilePanel='closed';selectedHand=null;closeDialog();render();return;}
 if(!confirmed&&confirmEndTurn(s,a)){manualUI.confirm=a.id;manualUI.mobilePanel='actions';render();return;}
 if(battle.practice&&s.decision?.type!=='manaPayment'){battleUndo.push(clone(s));battleUndo=battleUndo.slice(-20);}
 const playback=ensureAIPlayback(),before=playback.capture();playback.reset();recordBattleAction(battle,a,{manualMana:true},step);playback.recordHuman(before);selectedHand=null;manualUI={...newManualUI(),aiSpeed:manualUI.aiSpeed,fast:manualUI.fast,logOpen:manualUI.logOpen,choiceOrigin:manualUI.choiceOrigin,choiceContext:manualUI.choiceContext};closeDialog();render();scheduleAI();
}
function showManualShields(player,page=0){if(!battle)return;const model=manualShieldModel(battle.state,manualUI,player);if(!model)return;const pane=pageWindow(model.actions,page,8);showDialog(`${player?'相手':'自分'}のシールド · ${model.groups.length}つ`,`<p class="small mb16">緑色の番号を選べます。複数のシールドは下の操作から選びます。</p><div class="shield-picker-grid">${model.groups.map(g=>`<article><button class="shield-picker-tile ${g.action?'is-target':''}" ${g.action?`data-action="battle-step" data-index="${g.action.id}"`:'disabled'} aria-label="シールド${g.number}${g.action?'を選ぶ':''}"><strong>${g.number}</strong>${g.count>1?`<span>${g.count}枚の束</span>`:''}${g.ex?'<span>EXライフ</span>':''}</button>${g.faceUp.map(c=>`<button class="shield-picker-face" data-action="card-detail" data-id="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</article>`).join('')||'<p class="small">シールドはありません。</p>'}</div>${pane.items.length?`<h3 class="mt24">選べる操作</h3><div class="shield-picker-actions mt16">${pane.items.map(a=>`<button class="btn" data-action="battle-step" data-index="${a.id}">${esc(a.label)}</button>`).join('')}</div>`:''}`,`${pane.pages>1?`<button class="btn" data-action="manual-shields" data-player="${player}" data-page="${pane.index-1}" ${pane.index===0?'disabled':''}>前へ</button><span>${pane.index+1} / ${pane.pages}</span><button class="btn" data-action="manual-shields" data-player="${player}" data-page="${pane.index+1}" ${pane.index+1>=pane.pages?'disabled':''}>次へ</button>`:''}<button class="btn primary" data-action="close-dialog">盤面に戻る</button>`);}
function showManualField(player,page=0){if(!battle||![0,1].includes(player))return;const s=battle.state,m=manualModel(s,manualUI),pane=pageWindow(s.players[player].battle,page,manualUI.choicePageSize||4);showDialog(`${player?'相手':'自分'}の場 · ${s.players[player].battle.length}体`,`<div class="manual-field-list">${pane.items.map(x=>{const c=card(x),selectable=boardChoice(s,manualUI,player,'battle',x.uid)||(!player&&m.actions.some(a=>a.kind==='attack'&&a.uid===x.uid));return `<article>${art(c.id)}<div class="grow"><strong>${esc(c.name)}</strong><small>${x.sealed?'封印 '+(s.players[player].seals||[]).filter(y=>y.sealOf===x.uid).length+'枚':c.type==='gear'?'クロスギア · '+(x.crossedTo?'装備：'+esc(card(s.players[player].battle.find(y=>y.uid===x.crossedTo.uid))?.name||''):'未クロス'):c.type==='seed'?'タマシード':c.type==='field'?'フィールド':'パワー '+esc(power(x,false,s))} · ${x.tapped?'タップ中':'アンタップ'}${attackLocked(s,player,x)?' · 攻撃不可':''}</small></div><button class="btn sm" data-action="${selectable?'manual-creature':'manual-status'}" data-player="${player}" data-uid="${esc(x.uid)}">${selectable?'選ぶ':'状態'}</button>${selectable?`<button class="btn sm" data-action="manual-status" data-player="${player}" data-uid="${esc(x.uid)}">状態</button>`:''}<button class="btn sm" data-action="card-detail" data-id="${esc(c.id)}">能力</button>${x.under?.length?`<button class="btn sm" data-action="evolution-stack" data-player="${player}" data-uid="${esc(x.uid)}">${sourceCardLabel(x,isEvolution(x))}</button>`:''}</article>`;}).join('')||'<p class="small">クリーチャーはいません。</p>'}</div>`,`<button class="btn" data-action="manual-field" data-player="${player}" data-page="${pane.index-1}" ${pane.index===0?'disabled':''}>前へ</button><span>${pane.index+1} / ${pane.pages}</span><button class="btn" data-action="manual-field" data-player="${player}" data-page="${pane.index+1}" ${pane.index+1>=pane.pages?'disabled':''}>次へ</button><button class="btn primary" data-action="close-dialog">盤面に戻る</button>`);}
function showManualMethods(kind,page=0){if(!battle)return;const m=manualModel(battle.state,manualUI),actions=m.actions.filter(a=>a.player===0&&(kind==='attack'?a.kind==='attack'&&a.uid===m.attacker:(a.kind==='play'&&['mana','grave','deck','extra','battle'].includes(a.origin))||(a.kind==='mugenStart'&&a.uid!==manualUI.hand)||a.kind==='pandora'&&a.origin!=='hand'||a.kind==='hyper'||a.kind==='crossGear')),pane=pageWindow(actions,page,manualUI.choicePageSize||4),action=kind==='attack'?'manual-target-list':'manual-extra-methods';showDialog(kind==='attack'?'攻撃先を選ぶ':'場・山札・マナ・墓地などから使う',`<div class="stack">${pane.items.map(a=>`<button class="btn" data-action="battle-step" data-index="${a.id}">${esc(a.label)}</button>`).join('')||'<p class="small">選べる行動はありません。</p>'}</div>`,`<button class="btn" data-action="${action}" data-page="${pane.index-1}" ${pane.index===0?'disabled':''}>前へ</button><span>${pane.index+1} / ${pane.pages}</span><button class="btn" data-action="${action}" data-page="${pane.index+1}" ${pane.index+1>=pane.pages?'disabled':''}>次へ</button><button class="btn primary" data-action="close-dialog">盤面に戻る</button>`);}
