const searchInputIds=new Set(['home-deck-search','deck-card-search','starter25-search','manual-choice-search','ocr-card-search','card-search','opponent-search']);
const composingSearchInputs=new WeakSet(),appliedSearchValues=new WeakMap();
function applySearchInput(e){
 if(e.isConnected===false||composingSearchInputs.has(e)||appliedSearchValues.get(e)===e.value)return;
 const value=e.value,start=e.selectionStart,end=e.selectionEnd??start,direction=e.selectionDirection||'none';
 appliedSearchValues.set(e,value);
 if(e.id==='home-deck-search')homeQuery=value;
 else if(e.id==='deck-card-search')deckQuery=value;
 else if(e.id==='starter25-search')starterQuery=value;
 else if(e.id==='manual-choice-search'){manualUI.filter=value;manualUI.choicePage=0;}
 else if(e.id==='card-search'){query=value;page=0;}
 else if(e.id==='opponent-search')opponentQuery=value;
 else if(e.id==='ocr-card-search'){const matches=value.trim()?cards.filter(c=>norm(c.name).includes(norm(value))).slice(0,20):[];$('#ocr-search-results').innerHTML=matches.length?matches.map(c=>`<button class="opponent full" data-action="ocr-pick-apply" data-index="${e.dataset.index}" data-id="${c.id}">${esc(c.name)}</button>`).join(''):'候補がありません。カード名を入力してください。';return;}
 if(e.id==='starter25-search')refreshStarter25();else render();
 const replacement=$('#'+e.id);
 if(replacement){appliedSearchValues.set(replacement,value);replacement.focus({preventScroll:true});if(start!==null)replacement.setSelectionRange(start,end,direction);}
}
document.addEventListener('compositionstart',event=>{if(searchInputIds.has(event.target.id))composingSearchInputs.add(event.target);});
document.addEventListener('compositionend',event=>{const e=event.target;if(!searchInputIds.has(e.id))return;composingSearchInputs.delete(e);
 // Browsers send the final input before or after compositionend. Finish once,
 // after the committed text is available, without removing a live IME field.
 Promise.resolve().then(()=>applySearchInput(e));
});
document.addEventListener('input',event=>{const e=event.target;if(searchInputIds.has(e.id)){if(!event.isComposing&&!composingSearchInputs.has(e))applySearchInput(e);return;}if(e.id==='deck-name'&&edit){edit.name=e.value;return;}if(e.id==='replay-range'){replayIndex=Number(e.value);render();}});
document.addEventListener('change',async event=>{const e=event.target;if(e.id==='home-deck-sort'){if(['selected','updated','name'].includes(e.value)){homeOrder=e.value;render();$('#home-deck-sort')?.focus({preventScroll:true});}return;}if(e.id==='deck-sort'){if(['cost','name','count'].includes(e.value)){deckSort=e.value;render();$('#deck-sort')?.focus({preventScroll:true});}return;}if(e.id==='online-deck'){onlineDeckId=e.value;return;}if(e.id==='online-code'){onlineCode=e.value;return;}
 if(e.id==='cost-filter'){costFilter=e.value;page=0;render();}if(e.id==='type-filter'){typeFilter=e.value;page=0;render();}
 if(e.id==='match-count'){count=Number(e.value);render();$('#match-count')?.focus({preventScroll:true});}if(e.id==='match-first'){first=e.value;render();$('#match-first')?.focus({preventScroll:true});}if(e.id==='all-opponents'){allOpp=e.checked;render();}if(e.id==='practice-mode')practice=e.checked;
 if(e.id==='support-file')await processSupportPhoto(e.files[0]);
 if(e.id==='photo-file'||e.id==='camera-file')await processPhoto(e.files[0]);
 if(e.matches('.ocr-card')){const r=photo.rows[Number(e.dataset.index)];r.id=e.value;r.confirmed=false;render();}
 if(e.matches('.ocr-confirm')){photo.rows[Number(e.dataset.index)].confirmed=e.checked;render();}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click();}});
dialog.addEventListener('close',()=>{accountDialog=null;accountImportPreview=null;aiPlayback?.start();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('beforeunload',e=>{if(edit||running||(battle&&battle.state.winner===null)){e.preventDefault();e.returnValue='';}});
async function boot(){try{const responses=await Promise.all([fetch('cards.json?v='+APP_VERSION,{cache:'no-cache'}),fetch('catalogue.json'),fetch('details.json?v=0.121.0')]);if(responses.some(r=>!r.ok))throw Error('カード情報を読み込めません');[metadata,nameMetadata,detailsMetadata]=await Promise.all(responses.map(r=>r.json()));if((!detailsMetadata.previewOnly&&detailsMetadata.processedCount!==nameMetadata.registeredNameCount)||nameMetadata.cards.length!==nameMetadata.registeredNameCount)throw Error('カード名データの件数が一致しません');battleCards=metadata.cards;registry=createCatalogue(nameMetadata,battleCards,detailsMetadata);cards=registry.cards;cardTypes=[...new Set(cards.flatMap(c=>cardFaces(c).map(f=>f.typeText)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja'));cardCosts=[...new Set(cards.flatMap(c=>cardFaces(c).map(f=>f.cost)).filter(Number.isSafeInteger))].sort((a,b)=>a-b);cards.forEach(searchText);setCards(battleCards);environmentDecks=resolveEnvironmentDecks(registry);starterDecks=resolveStarter25Decks(registry);for(const d of [...saved.decks,...saved.friends]){try{d.cards=registry.resolveRows(d.cards);}catch{}}const params=new URLSearchParams(location.search);if(params.get('view')==='account')view='account';if(params.get('view')==='online'||params.get('room')){view='online';onlineCode=params.get('room')||'';}const resumed=restoreUpdatedSession();initPlaytime();if(view==='challenge'||battle?.challengeId)await loadChallengeDecks();render();if(resumed){sessionStorage.removeItem(UPDATE_RESUME_KEY);if(battle&&view==='manual'&&!ensureAIPlayback().snapshot().paused)ensureAIPlayback().togglePause();toast(battle?'更新しました。対戦は一時停止した状態で再開できます':edit?'更新しました。編集中の内容を復元しました':'更新しました。保存済みのデッキはそのまま使えます');}if(updateResumeRecovery)showUpdateRecovery();initAppUpdates();if(view==='online')void initOnline();else void initAccount();
 if(location.hash.startsWith('#deck=')){try{if(location.hash.length>32768)throw Error('共有データが大きすぎます');const b=atob(decodeURIComponent(location.hash.slice(6)));const data=JSON.parse(new TextDecoder().decode(Uint8Array.from(b,c=>c.charCodeAt(0))));const d=parseDeckText(JSON.stringify(data));d.category='友達';d.description='共有リンクから読み込んだデッキです。';saved.friends.push(d);persist();history.replaceState(null,'',location.pathname);view='battle';selectedOpp=d.id;render();toast('共有されたデッキを相手一覧に追加しました');}catch{toast('共有リンクの形式が正しくないか、未対応のカードが含まれています');}}
 }catch(e){root.innerHTML=`<div class="boot"><h2>読み込みできませんでした</h2><p>${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">再読み込み</button></div>`;}}
window.addEventListener('online',()=>{if(view==='online')void onlineClient?.refresh();});
document.addEventListener('visibilitychange',()=>{onlineClient?.setActive(view==='online'&&!document.hidden);if(document.hidden)aiPlayback?.suspend();else{if(view==='manual')scheduleAI();void appUpdates?.check();}});
boot();
